package main

import (
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func skipSpace() bool {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	return pos < len(data)
}

func token() string {
	skipSpace()
	s := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[s:pos])
}

func num() int64 {
	skipSpace()
	neg := false
	if pos < len(data) && (data[pos] == '-' || data[pos] == '+') {
		neg = data[pos] == '-'
		pos++
	}
	var v int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		v = v*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, x := num(), num()
	out := []byte{}
	// Skipping a node is the same as linking its predecessor to its successor.
	for i := int64(0); i < n; i++ {
		v := num()
		if v > x {
			continue
		}
		if len(out) > 0 {
			out = append(out, ' ')
		}
		out = strconv.AppendInt(out, v, 10)
	}
	out = append(out, '\n')
	os.Stdout.Write(out)
}
